// Generated by OrchestKit Claude Plugin
// Created: 2026-08-12 (#3321 claim 2)

/**
 * Measured context occupancy, read from CC's own reported usage.
 *
 * WHY THIS EXISTS (#3321 claim 2)
 * -------------------------------
 * Every context-pressure heuristic in this repo used to compare
 * `AccumState.estimatedTokens` against a percentage of the context window.
 * That is a unit mismatch, not a calibration problem:
 *
 *   - the numerator counted only what `posttool/context-crossing-warn` saw,
 *     and that hook is registered under matcher `Read|Grep|Glob|WebFetch|
 *     WebSearch` (hooks.json), so it counts NOTHING from Bash, Edit, Write,
 *     agent results, MCP, or conversation turns;
 *   - the denominator was the WHOLE window.
 *
 * A counter measuring a fraction of context checked against a full-context
 * bar. Across 2,248 recorded PreCompact decisions the imminent gate returned
 * `belowImminentZone` 2,246 times and fired 0 times since the gate landed;
 * the highest value any of 93 real state files ever held was 707,702 against
 * an 850,000 bar. Lowering the bar would NOT have fixed it — the denominator
 * was wrong, so the reading was never comparable in the first place.
 *
 * The remedy is to stop estimating. CC writes its real per-turn usage into
 * the session transcript, and `transcript_path` is part of the base payload
 * every hook event receives (verified in the 2.1.228 binary: the shared
 * builder returns `{session_id, transcript_path, cwd, prompt_id,
 * permission_mode, agent_id, agent_type, effort}`). The last assistant turn's
 * `usage` is the prompt CC actually sent, so
 *
 *     input_tokens + cache_creation_input_tokens + cache_read_input_tokens
 *
 * IS the occupied context at that turn — the same unit as the window, from
 * the API rather than from `Math.ceil(text.length / 3.5)`.
 */

import { openSync, fstatSync, readSync, closeSync } from 'node:fs';

/**
 * Bytes read from the tail of the transcript. Transcripts run to several MB,
 * so the whole file is never loaded. Real assistant entries average ~1.5KB,
 * and only the LAST one is needed, so this window holds many candidates even
 * when a huge tool_result sits between them.
 */
const TAIL_READ_BYTES = 256 * 1024;

interface TranscriptUsage {
  input_tokens?: unknown;
  cache_creation_input_tokens?: unknown;
  cache_read_input_tokens?: unknown;
}

interface TranscriptEntry {
  type?: unknown;
  isSidechain?: unknown;
  message?: { usage?: TranscriptUsage } | unknown;
}

function asCount(value: unknown): number {
  const n = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(n) && n > 0 ? n : 0;
}

function usageOf(entry: TranscriptEntry): TranscriptUsage | null {
  const message = entry.message;
  if (!message || typeof message !== 'object') return null;
  const usage = (message as { usage?: unknown }).usage;
  if (!usage || typeof usage !== 'object') return null;
  return usage as TranscriptUsage;
}

/**
 * Occupied context in tokens at the last main-chain assistant turn, or null
 * when the transcript is missing, unreadable, or holds no usable entry.
 *
 * Sidechain entries are skipped: those are a subagent's turns, and a
 * subagent's context is not the session's.
 *
 * Null means "no measurement", NEVER "zero". Callers must treat it as "do
 * not gate on this" rather than as a low reading — guessing low is how the
 * estimator produced a gate that could not fire.
 */
export function readMeasuredContextTokens(transcriptPath: string | undefined): number | null {
  if (!transcriptPath) return null;

  let fd: number | null = null;
  try {
    fd = openSync(transcriptPath, 'r');
    const size = fstatSync(fd).size;
    if (size === 0) return null;

    const readSize = Math.min(size, TAIL_READ_BYTES);
    const start = size - readSize;
    const buf = Buffer.allocUnsafe(readSize);
    const bytesRead = readSync(fd, buf, 0, readSize, start);
    closeSync(fd);
    fd = null;

    const lines = buf.toString('utf8', 0, bytesRead).split('\n');
    // When the read started mid-file the first line is a fragment.
    if (start > 0) lines.shift();

    for (let i = lines.length - 1; i >= 0; i--) {
      const line = lines[i].trim();
      if (!line) continue;
      let entry: TranscriptEntry;
      try {
        entry = JSON.parse(line) as TranscriptEntry;
      } catch {
        continue;
      }
      if (entry.type !== 'assistant') continue;
      if (entry.isSidechain === true) continue;
      const usage = usageOf(entry);
      if (!usage) continue;

      const total =
        asCount(usage.input_tokens) +
        asCount(usage.cache_creation_input_tokens) +
        asCount(usage.cache_read_input_tokens);
      if (total > 0) return total;
    }

    return null;
  } catch {
    if (fd !== null) {
      try {
        closeSync(fd);
      } catch {
        /* ignore */
      }
    }
    return null;
  }
}

export default readMeasuredContextTokens;
